/* ==========================================================
   Paleta
   Rojo   #8d0801 → botón "Agenda", .active y botones de avance
   Madera #D4A373 → hover y delineados
   Beige  #F4E3B2 → placeholders y orbes
   Fondo  #F4F4F4 · Texto #1A1A1A
   ========================================================== */
:root {
  --red: #8d0801;
  --wood: #D4A373;
  --beige: #F4E3B2;
  --bg: #F4F4F4;
  --white: #FFFFFF;
  --ink: #1A1A1A;
  --shadow: 0 24px 48px -12px rgba(0, 0, 0, .18);
  color-scheme: light;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Space Grotesk', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--ink);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

button { font: inherit; }

h1, h2, h3, .btn {
  font-family: 'Oswald', sans-serif;
}

/* ==========================================================
   Orbes animados en los espacios negativos (pantallas 2 a 4)
   ========================================================== */
.bg {
  position: fixed;
  inset: 0;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  animation: flotar 30s ease-in-out infinite alternate;
}

.o1 { width: 520px; height: 520px; background: var(--red);  opacity: .07; top: -200px; left: -180px; }
.o2 { width: 460px; height: 460px; background: var(--beige); opacity: .08; bottom: -180px; right: -160px; animation-duration: 36s; animation-delay: -10s; }
.o3 { width: 300px; height: 300px; background: var(--beige); opacity: .06; top: 55%; right: -100px; animation-duration: 32s; animation-delay: -18s; }

@keyframes flotar {
  0%   { transform: translate(0, 0) scale(1); }
  50%  { transform: translate(60px, -40px) scale(1.06); }
  100% { transform: translate(-30px, 30px) scale(.97); }
}

/* ==========================================================
   Pantallas: solo una visible a la vez
   ========================================================== */
.app {
  position: relative;
  z-index: 1;
  min-height: 100vh;
}

.screen {
  display: none;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1100px;
  margin: 0 auto;
  padding: 72px 32px 56px;
}

.screen.is-visible {
  display: flex;
  animation: fadeIn .5s ease both;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: none; }
}

/* ==========================================================
   Pantalla 1 (Hero) · foto del local en base64
   Reemplaza PEGA_AQUI_TU_BASE64_DE_IMAGE_AC539C por tu base64 real
   ========================================================== */
#pantalla-1,
.pantalla-1 {
  /* Ocupa toda la pantalla */
  width: 100%;
  height: 100vh;
  min-height: 100vh;
  max-width: none;
  margin: 0;
  padding: 0;
  overflow: hidden;

  /* Centrado vertical y horizontal del título y el botón.
     No declaro display aquí: .screen ya lo controla y, si lo pusiera,
     la pantalla no se ocultaría al cambiar de paso. */
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #FFFFFF;

  /* Overlay oscuro (70%) + foto de fondo en base64.
     cover + center center: la foto llena la pantalla sin distorsionarse. */
  background-color: #1A1A1A; /* respaldo si la imagen no carga */
  background-image:
    linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)),
    url('data:image/jpeg;base64,');
  background-position: center center;
  background-size: cover;
  background-repeat: no-repeat;
}

.inicio h1 {
  font-weight: 700;
  font-size: clamp(2.6rem, 8vw, 5.5rem);
  letter-spacing: 3px;
  text-transform: uppercase;
  line-height: 1.05;
  color: #FFFFFF;
  margin-bottom: 48px;
}

.inicio .btn {
  padding: 18px 44px;
  font-size: 1rem;
  letter-spacing: 1px;
}

/* ==========================================================
   Títulos de paso
   ========================================================== */
.titulo-paso {
  text-align: center;
  margin: 24px 0 56px;
}

.titulo-paso h2 {
  font-weight: 700;
  font-size: clamp(1.5rem, 4vw, 2.2rem);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.titulo-paso h2::after {
  content: "";
  display: block;
  width: 56px;
  height: 3px;
  margin: 16px auto 0;
  background: var(--wood);
}

/* ==========================================================
   Botones (esquinas rectas)
   ========================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 32px;
  border: 2px solid transparent;
  border-radius: 0;
  font-weight: 600;
  font-size: .95rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  cursor: pointer;
  transition: background .25s, color .25s, border-color .25s, transform .2s, opacity .2s;
}

.btn:hover:not(:disabled) { transform: translateY(-2px); }

.btn-primary {
  background: var(--red);
  color: var(--white);
}

.btn-primary:hover:not(:disabled) {
  background: var(--wood);
  color: var(--ink);
}

.btn-primary:disabled {
  opacity: .35;
  cursor: not-allowed;
}

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}

.btn-ghost:hover {
  background: var(--wood);
  border-color: var(--wood);
}

.acciones {
  margin-top: auto;
  padding-top: 64px;
  display: flex;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

/* ==========================================================
   Carrusel automático (solo barberos)
   ========================================================== */
.carrusel {
  overflow: hidden;
  padding: 16px 0 24px;
}

.track {
  display: flex;
  gap: 40px;
  width: max-content;
  will-change: transform;
}

/* ==========================================================
   Tarjetas
   ========================================================== */
.card {
  background: var(--white);
  color: var(--ink);
  border: 2px solid transparent;
  box-shadow: var(--shadow);
  padding: 20px;
  text-align: center;
  cursor: pointer;
  transition: border-color .25s, background .25s, color .25s, transform .25s;
}

.card:hover {
  border-color: var(--wood);
  transform: translateY(-4px);
}

.card.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.card.active .ph {
  background: rgba(255, 255, 255, .12);
  color: var(--white);
}

.barbero { flex: 0 0 260px; }

.ph {
  height: 300px;
  background: var(--beige);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', sans-serif;
  font-size: .8rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(26, 26, 26, .4);
  transition: background .25s;
}

.card h3 {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-top: 22px;
}

/* Servicios: cuadrícula fija */
.grid-servicios {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.servicio .ph { height: 340px; }

/* ==========================================================
   Paso 3: calendario y horarios
   ========================================================== */
.fecha-hora {
  display: grid;
  grid-template-columns: minmax(300px, 400px) 1fr;
  gap: 64px;
  align-items: start;
}

.cal,
.slots {
  background: var(--white);
  box-shadow: var(--shadow);
  padding: 36px;
}

.cal h3,
.slots h3 {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  text-align: center;
  margin-bottom: 28px;
}

.cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  text-align: center;
}

.dow {
  font-family: 'Oswald', sans-serif;
  font-size: .8rem;
  opacity: .5;
  padding-bottom: 8px;
}

.day {
  aspect-ratio: 1;
  border: none;
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font-size: .9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background .25s, color .25s;
}

.day:hover:not(.active) { background: var(--wood); }

.day.active {
  background: var(--red);
  color: var(--white);
}

.day.blank { visibility: hidden; }

.slots-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.slot {
  padding: 14px 8px;
  background: var(--bg);
  border: 2px solid transparent;
  color: var(--ink);
  font-family: 'Oswald', sans-serif;
  font-size: .9rem;
  letter-spacing: .5px;
  cursor: pointer;
  transition: background .25s, color .25s, border-color .25s;
}

.slot:hover:not(.active) { border-color: var(--wood); }

.slot.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

/* ==========================================================
   Toast de confirmación
   ========================================================== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 32px;
  transform: translate(-50%, 160%);
  background: var(--ink);
  color: var(--white);
  padding: 16px 28px;
  border-bottom: 3px solid var(--wood);
  font-family: 'Oswald', sans-serif;
  font-size: .9rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-align: center;
  box-shadow: var(--shadow);
  transition: transform .4s ease;
  z-index: 10;
  max-width: 90vw;
}

.toast.show { transform: translate(-50%, 0); }

/* ==========================================================
   Responsive
   ========================================================== */
@media (max-width: 900px) {
  .screen { padding: 56px 24px; }
  .fecha-hora { grid-template-columns: 1fr; gap: 40px; }
  .grid-servicios { grid-template-columns: 1fr; }
  .servicio .ph { height: 240px; }
}

@media (max-width: 480px) {
  .screen { padding: 44px 18px; }
  .barbero { flex-basis: 220px; }
  .ph { height: 240px; }
  .cal, .slots { padding: 24px; }
  .slots-grid { grid-template-columns: repeat(2, 1fr); }
  .acciones .btn { flex: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .orb,
  .screen.is-visible { animation: none; }
}